import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
export async function runMotionScatterPathsSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));let revision=0;
 const values=[{x:20,y:25,size:40},{x:60,y:40,size:25},{x:35,y:70,size:60}];
 async function ready(count=8){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('[data-nw-stream-slot]').length===count&&d.querySelector('.nw-scatter-dial-surface')&&d.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth);},{timeout:15000},count);}
 async function change(selector,value,count=8){const mark='path-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.pathOld=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.pathOld!==mark;},{},mark);await ready(count);}
 async function step(index){await page.select('[data-motion-scatter-step]',String(index));}
 async function selectFirst(){await page.click('[data-motion-library-tab="elements"]');const id=await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.id);await page.click('[data-motion-layer="'+id+'"]');return id;}
 async function pose(p,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{p,gid})=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(p);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,tiles:n.__nwMotionInstances,clip:n.__nwMotionClip}));},{p,gid});}
 function checkPoint(cards,index){const {clip,tiles}=cards[0],point=values[index],pad=Math.min(clip.width,clip.height)*.06,tile=tiles[0];assert.ok(tile);assert.ok(Math.abs(tile.center.x-(clip.left+pad+(clip.width-2*pad)*point.x/100))<.00001);assert.ok(Math.abs(tile.center.y-(clip.top+pad+(clip.height-2*pad)*point.y/100))<.00001);assert.ok(Math.abs(tile.cardScale-point.size/100)<.00001);}
 async function checkFields(){for(let i=0;i<3;i++){await step(i);for(const key of ['x','y','size'])assert.equal(await page.$eval('[data-motion-scatter-point="'+key+'"]',n=>+n.value),values[i][key]);}}
 async function exportFrame(gid){await page.evaluate(()=>{const f=document.createElement('iframe');f.id='scatter-path-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#scatter-path-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#scatter-path-export').contentDocument.querySelector('.nw-scatter-dial-surface'),{},gid);}
 async function saveAndPreview(gid){
  const mark='scatter-save-'+(++revision);await page.$eval('#preview',(f,mark)=>f.contentDocument.body.dataset.scatterSaveOld=mark,mark);await page.click('[data-motion-save]');
  await page.waitForFunction(({gid,mark})=>{const f=document.querySelector('#preview'),d=f?.contentDocument,slots=d&&Array.from(d.querySelectorAll('[data-nw-stream-slot]'));return d?.body&&d.body.dataset.scatterSaveOld!==mark&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[gid]&&d.querySelector('.nw-scatter-dial-surface')&&slots.length===8&&slots.every(n=>n.__nwMotionInstances&&n.querySelector('img')?.complete&&n.querySelector('img').naturalWidth);},{timeout:15000},{gid,mark});
 }
 try{
  await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{text:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const outside=await page.evaluate(()=>JSON.stringify(sec().elements[0]));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="scatter-dial"]');await ready();assert.equal(await page.$eval('[data-motion-scatter-panel]',n=>n.hidden),true);const id=await selectFirst();assert.equal(await page.$eval('[data-motion-scatter-panel]',n=>n.hidden),false);
  for(const [key,spec] of [['x','0,100,0.1'],['y','0,100,0.1'],['size','5,150,1']])assert.equal(await page.$eval('[data-motion-scatter-point="'+key+'"]',n=>[n.min,n.max,n.step].join(',')),spec);
  const original=[];for(const p of [0,30/532,60/532])original.push(await pose(p));const ring=await pose(.51);assert.equal(await page.$eval('[data-motion-scatter-reset]',n=>n.disabled),true);
  for(let i=0;i<3;i++){await step(i);for(const key of ['x','y','size'])await change('[data-motion-scatter-point="'+key+'"]',String(values[i][key]));await page.click('[data-motion-scatter-view]');assert.ok(Math.abs(await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument;return f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].progress();})-i*30/532)<.00001);const cards=await pose(i*30/532);checkPoint(cards,i);for(let slot=1;slot<8;slot++)assert.deepEqual(cards[slot],original[i][slot]);checkPoint(await pose((1-i*30/532)%1),i);}
  assert.deepEqual(await pose(.51),ring);await step(0);await page.$eval('[data-motion-scatter-point="x"]',n=>{n.value='';n.dispatchEvent(new Event('change',{bubbles:true}));});assert.equal(await page.$eval('[data-motion-scatter-point="x"]',n=>+n.value),20);await change('[data-motion-scatter-point="x"]','999');assert.equal(await page.$eval('[data-motion-scatter-point="x"]',n=>+n.value),100);await change('[data-motion-scatter-point="x"]','20');
  await change('[data-motion-stream-order]','6');assert.equal(await page.$eval('[data-motion-scatter-panel]',n=>n.hidden),true);await change('[data-motion-stream-order]','1');await checkFields();assert.equal(await selectFirst(),id);await page.click('[data-motion-duplicate]');await ready(9);assert.equal(await page.$eval('[data-motion-scatter-panel]',n=>n.hidden),true);await change('[data-motion-stream-order]','2',9);await checkFields();await page.click('[data-motion-element-remove]');await ready();await selectFirst();await checkFields();
  const replacement=await page.$eval('[data-motion-content-panel] select[data-motion-content]',n=>Array.from(n.options).find(o=>o.value&&o.value!==n.value)?.value);assert.ok(replacement);await change('[data-motion-content-panel] select[data-motion-content]',replacement);await checkFields();await pose(0);
  const center=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,n=d.querySelector('[data-nw-stream-slot]'),t=n.__nwMotionInstances[0],host=n.offsetParent,c=d.querySelector('.nw-scatter-dial-surface'),k=c.width/host.clientWidth,fr=f.getBoundingClientRect(),hr=host.getBoundingClientRect();return{alpha:c.getContext('2d').getImageData(Math.floor(t.center.x*k),Math.floor(t.center.y*k),1,1).data[3],x:fr.left+f.clientLeft+hr.left+t.center.x*hr.width/host.clientWidth,y:fr.top+f.clientTop+hr.top+t.center.y*hr.height/host.clientHeight};});assert.ok(center.alpha>10);const second=(await pose(0))[1].id;await page.click('[data-motion-layer="'+second+'"]');await page.mouse.click(center.x,center.y);assert.equal(await page.$eval('[data-motion-layer][aria-pressed="true"]',n=>n.dataset.motionLayer),id);await(await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/scatter-paths-desktop.png'});
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Dispersión personalizada');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.deepEqual(saved.elements.filter(e=>e.nwStreamSlot)[0].nwScatterPath,values);assert.equal(saved.config.stream.scatterPaths,undefined);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();await selectFirst();await checkFields();await page.click('[data-motion-insert-group]');const gid=await page.evaluate(()=>sec().elements.find(e=>e.nwMotionInstance).id);assert.equal(await page.evaluate(()=>JSON.stringify(sec().elements[0])),outside);await page.waitForFunction(gid=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},gid);checkPoint(await pose(0,'#preview',gid),0);
  await exportFrame(gid);for(let i=0;i<3;i++)checkPoint(await pose(i*30/532,'#scatter-path-export',gid),i);await page.evaluate(()=>document.querySelector('#scatter-path-export').remove());const timeProject=await page.evaluate(()=>JSON.stringify(project));assert.deepEqual(await page.evaluate(()=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.nwStreamSlot).nwScatterPath),values);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),gid);await ready();await selectFirst();await step(0);await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.pathResetOld='old');await page.click('[data-motion-scatter-reset]');await page.waitForFunction(()=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&!d.body.dataset.pathResetOld;});await ready();assert.equal(await page.$eval('[data-motion-scatter-reset]',n=>n.disabled),true);assert.ok(Math.abs(await page.$eval('[data-motion-scatter-point="x"]',n=>+n.value)-390.857/19.2)<.001);await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),timeProject);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),gid);await ready();await selectFirst();await checkFields();await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="turns"]','3');
  // Hold the real preview queue to exercise a saved group whose old time
  // runtime is still present. Group existence alone must not end the wait.
  await page.evaluate(()=>{clearTimeout(previewTimer);window.__nwScatterSaveGate={schedule:schedulePreview,held:false};schedulePreview=function(){window.__nwScatterSaveGate.held=true;};});let refreshed=false;const savedPreview=saveAndPreview(gid).then(()=>{refreshed=true;});await page.waitForFunction(()=>window.__nwScatterSaveGate?.held);assert.equal(await page.evaluate(()=>sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance.source),'scroll');assert.equal((await pose(.2,'#preview',gid))[0].tiles[0].stage,'ring');assert.equal(refreshed,false,'Save wait must stay pending while the old time preview is present');await page.evaluate(()=>{schedulePreview=window.__nwScatterSaveGate.schedule;delete window.__nwScatterSaveGate;schedulePreview();});await savedPreview;console.log('Scatter save: stale time preview reproduced; wait resumes only with the fresh scroll document, complete images and geometry.');const scrollProject=await page.evaluate(()=>JSON.stringify(project));checkPoint(await pose(.2,'#preview',gid),0);await exportFrame(gid);checkPoint(await pose(.2,'#scatter-path-export',gid),0);await page.evaluate(()=>document.querySelector('#scatter-path-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),timeProject);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scrollProject);
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),gid);await ready();await selectFirst();await checkFields();checkPoint(await pose(.2),0);await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.2),await pose(.8));await page.emulateMediaFeatures([]);await(await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/scatter-paths-mobile.png'});await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),scrollProject);
  console.log('Scatter per-image paths: three editable XY/size stages, independent images/ring and coherent return, bounds/reset/view, reorder/inactive slots/duplicate/replace, actual canvas pixels/native picking, Library/group/migration, resized export/time/scroll/history/mobile/reduced motion and isolated cancellation OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/scatter-paths-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#scatter-path-export')?.remove();if(window.__nwScatterSaveGate){schedulePreview=window.__nwScatterSaveGate.schedule;delete window.__nwScatterSaveGate;}clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
